    ll n, m, p;
    cin >> n >> m >> p;
    vector<ll> f(n + 1, 1), inv(n + 1, 1), finv(n + 1, 1);
    for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % p;
    inv[n] = pow(f[n], p - 2, p);
    for (int i = n - 1; i >= 0; i--) inv[i] = inv[i + 1] * (i + 1) % p;
    for (int i = 0; i <= n; i++) finv[i] = f[i] * inv[i] % p;
    auto C = [&](int a, int b) {
        if (a < 0 || b < 0 || a < b) return 0LL;
        return f[a] * inv[a - b] % p * inv[b] % p;
    };
    ll ans = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (i == j) continue;
            int d = abs(i - j);
            int L = min(i, j), R = max(i, j);
            int len = R - L + 1;
            if (len > m) continue;
            ll ways = 0;
            for (int k = 1; k <= m; k++) {
                if (k > len) break;
                ll c = C(len, k);
                ll a = f[k] * finv[k] % p;
                ll b = f[m - k] * finv[m - k] % p;
                ways = (ways + c * a % p * b % p) % p;
            }
            ans = (ans + d * ways % p) % p;
        }
    }
    cout << ans << endl;
    return 0;
}
