        for (int j = 0; j <= m; j++) {
            for (int k = 0; k < 2; k++) {
                if (dp[i][j][k] == 0) continue;
                // Place a person at position i+1
                if (j < m) {
                    dp[i+1][j+1][k] = (dp[i+1][j+1][k] + (ll)dp[i][j][k] * (j + 1) % MOD) % MOD;
                }
                // Don't place a person at position i+1
                dp[i+1][j][k] = (dp[i+1][j][k] + dp[i][j][k]) % MOD;
            }
        }
    }
    int ans = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++) {
            for (int k = 0; k < 2; k++) {
                if (dp[i][j][k] == 0) continue;
                int ways = C[n][i];
                ways = (ll)ways * C[i][j] % MOD;
                ways = (ll)ways * dp[i][j][k] % MOD;
                ans = (ans + (ll)ways * j % MOD) % MOD;
            }
        }
    }
