    vector<vector<ll>> ways(n+1, vector<ll>(m+1, 0));

    for (int i = 0; i <= n; i++) {
        ways[i][0] = 1;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            ways[i][j] = (ways[i-1][j] + ways[i-1][j-1]) % p;
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % p;
            if (j >= 2) {
                dp[i][j] = (dp[i][j] + (i-1) * dp[i-1][j-2]) % p;
            }
            if (j >= 1) {
                dp[i][j] = (dp[i][j] + (i-1) * ways[i-1][j-1]) % p;
            }
        }
    }

    ll ans = dp[n][m];
    ans = (ans * mod_exp(2, m, p)) % p;

    cout << ans << endl;

    return 0;
}
